import Combine
import Foundation
import DamageKit

struct ModCardMetadata: Codable, Hashable {
    let name: String
    let polarity: String
    let rarity: String
    let baseDrain: Int
    let maxRank: Int
    let compat: String
    let isArcane: Bool
    let art: String?
    let arcaneIcon: String?
    let frameTier: String?
    let modSet: String?
    let ranks: [String]
}

/// The compact index generated by `scripts/build_native_damage_data.py`.
/// It deliberately mirrors the website's Chinese weapon labels, but it is
/// plain JSON consumed by Swift — not a WebView payload.
struct NativeDamageWeaponEntry: Decodable, Identifiable, Hashable {
    let n: String
    let z: String
    let c: String
    let t: String
    let img: String
    let mr: Int
    let atk: [String]
    let inc: Bool

    var id: String { n }

    var categoryLabel: String {
        switch c {
        case "Primary": return "主武器"
        case "Secondary": return "副武器"
        case "Melee": return "近战"
        case "Archgun": return "Archwing 枪械"
        case "Exalted Weapon": return "显赫武器"
        default: return c
        }
    }

    var iconURL: URL? {
        guard !img.isEmpty else { return nil }
        return URL(string: "https://warframe-damage.com/data/img/\(img)")
    }
}

/// Read-only catalogue shared by the native calculator pages.
///
/// The data directory is a folder reference in the app bundle, so weapon JSON
/// files keep their names and DataStore can use the same lookup it uses in the
/// command-line verifier.  No JavaScript, local HTTP server, or WebKit is
/// involved after this point.
@MainActor
final class NativeDamageCatalog: ObservableObject {
    static let shared = NativeDamageCatalog()

    @Published private(set) var weapons: [NativeDamageWeaponEntry] = []
    @Published private(set) var enemies: [Enemy] = []
    @Published private(set) var translations: [String: String] = [:]
    @Published private(set) var loadError: String?

    private(set) var store: DataStore?
    private var dataRoot: URL?
    private var lowercasedTranslations: [String: String] = [:]
    private var modCards: [String: ModCardMetadata] = [:]
    private var lowercasedModCards: [String: ModCardMetadata] = [:]

    private init() {
        load()
    }

    init(root: URL?) {
        load(root: root)
    }

    func load(root explicitRoot: URL? = nil) {
        // Keep the calculator on the exact same resolver as the weapon list.
        // Folder references exist at `.app/DamageData`; asking Bundle to look
        // up the directory as a single resource can return nil even when the
        // directory was copied into the app correctly.
        guard let root = explicitRoot ?? DamageDataBundle.root() else {
            store = nil
            dataRoot = nil
            weapons = []
            enemies = []
            translations = [:]
            loadError = "计算器数据无法读取。请重新安装完整版本后重试。"
            return
        }

        do {
            let decoder = JSONDecoder()
            let weaponData = try Data(contentsOf: root.appendingPathComponent("weapons-list.json"))
            let enemyData = try Data(contentsOf: root.appendingPathComponent("data/json/enemies-min.json"))
            let localizationData = try Data(contentsOf: root.appendingPathComponent("zh-Hans.json"))
            weapons = try decoder.decode([NativeDamageWeaponEntry].self, from: weaponData)
            enemies = try decoder.decode([Enemy].self, from: enemyData)
            translations = try decoder.decode([String: String].self, from: localizationData)
            var lowercased: [String: String] = [:]
            lowercased.reserveCapacity(translations.count)
            for (key, value) in translations {
                lowercased[key.lowercased()] = value
            }
            lowercasedTranslations = lowercased
            let cardsURL = root.appendingPathComponent("mod-cards-zh.json")
            if let cardData = try? Data(contentsOf: cardsURL),
               let decodedCards = try? decoder.decode([String: ModCardMetadata].self, from: cardData) {
                modCards = decodedCards
                var lowerCards: [String: ModCardMetadata] = [:]
                lowerCards.reserveCapacity(decodedCards.count)
                for (key, value) in decodedCards {
                    lowerCards[key.lowercased()] = value
                }
                lowercasedModCards = lowerCards
            } else {
                modCards = [:]
                lowercasedModCards = [:]
            }
            store = DataStore(root: root)
            dataRoot = root
            loadError = nil
        } catch {
            store = nil
            dataRoot = nil
            weapons = []
            enemies = []
            translations = [:]
            lowercasedTranslations = [:]
            modCards = [:]
            lowercasedModCards = [:]
            loadError = "计算器数据无法读取。请重新安装完整版本后重试。"
        }
    }

    func local(_ english: String) -> String {
        translations[english] ?? lowercasedTranslations[english.lowercased()] ?? english
    }

    /// The upstream site locale covers weapon and Mod names well, but several
    /// Incarnon evolutions and Archon-shard effect strings are not keys in that
    /// table.  Keep their Chinese display text in the native client instead of
    /// making a Chinese UI fall back to an English calculation label.
    func localIncarnon(_ english: String) -> String {
        translations[english] ?? Self.incarnonFallbacks[english] ?? english
    }

    func localShard(_ english: String) -> String {
        translations[english] ?? Self.shardFallbacks[english] ?? english
    }

